// ===== p306 : le prologue montre ce qu'il raconte — chaque date a son tableau, peint et animé, à côté du texte,
// au lieu de l'île qui tourne seule : la carte d'al-Idrisi (le sud en haut), les ravines du peuple d'Hanuman,
// les pyramides de l'île sœur, la razzia, le planisphère de Cantino, la caravelle de Santa Apolonia,
// les armes du roi, les exilés de Fort-Dauphin, et les traces du Sud. =====
const PRL306={raf:0,cv:null,k:-1,t0:0};
// une vraie carte ancienne (fournie par l'auteur) : Madagascar « S. Laurentij », S. Apolonia, Do Mascarenhas, Do Cirne
const CARTE306=new Image();CARTE306.src='data:image/jpeg;base64,';
// la côte de l'Afrique de l'Est et Madagascar, en (longitude, latitude)
const CAF306=[[32,-34],[35.3,-24],[40.5,-15],[40.4,-10.5],[39.5,-5],[41,-2],[46,2],[50,8],[51,11.8],[45,11],[43,12.5],[44,14],[49,15.5],[52,16.5],[56.5,18],[59.5,22.5],[57,25]];
