function prl306Papier(x,W,H,t){const g=x.createRadialGradient(W/2,H/2,W*.1,W/2,H/2,W*.75);g.addColorStop(0,'#efe0b8');g.addColorStop(1,'#c9a870');x.fillStyle=g;x.fillRect(0,0,W,H);
 let s=7;const r=()=>((s=(s*9301+49297)%233280)/233280);for(let i=0;i<26;i++){x.fillStyle='rgba(120,80,30,'+(.03+r()*.05)+')';x.beginPath();x.arc(r()*W,r()*H,10+r()*60,0,7);x.fill()}
 x.strokeStyle='rgba(90,60,25,.6)';x.lineWidth=3;x.strokeRect(8,8,W-16,H-16);x.lineWidth=1;x.strokeRect(14,14,W-28,H-28)}
function prl306Cote(x,L,P,ferme){x.beginPath();L.forEach((q,i)=>{const [a,b]=P(q[0],q[1]);i?x.lineTo(a,b):x.moveTo(a,b)});if(ferme)x.closePath()}
function prl306Rose(x,cx,cy,R,col){x.save();x.translate(cx,cy);for(let i=0;i<16;i++){const a=i/16*Math.PI*2,l=i%2?R*.55:R;x.fillStyle=i%2?'rgba(60,40,20,.7)':col;x.beginPath();x.moveTo(0,0);x.lineTo(Math.cos(a-.12)*l*.25,Math.sin(a-.12)*l*.25);x.lineTo(Math.cos(a)*l,Math.sin(a)*l);x.lineTo(Math.cos(a+.12)*l*.25,Math.sin(a+.12)*l*.25);x.fill()}x.restore()}
function prl306Voile(x,cx,cy,s,type,t){x.save();x.translate(cx,cy);x.scale(s,s);const b=Math.sin(t*1.4)*.04;x.rotate(b);
 // coque galbée
 x.fillStyle='#5a3a22';x.beginPath();x.moveTo(-50,0);x.quadraticCurveTo(-46,16,-10,18);x.quadraticCurveTo(30,18,56,-6);x.lineTo(40,-2);x.lineTo(-44,-4);x.closePath();x.fill();
 x.strokeStyle='rgba(30,18,8,.6)';for(let i=1;i<4;i++){x.beginPath();x.moveTo(-46,i*4);x.quadraticCurveTo(0,i*4+6,48,-6+i*3);x.stroke()}
 x.strokeStyle='#3a2616';x.lineWidth=2;
 if(type==='latine'){x.beginPath();x.moveTo(2,-2);x.lineTo(0,-62);x.stroke();x.beginPath();x.moveTo(-44,-10);x.lineTo(30,-74);x.stroke();
  x.fillStyle='#e6d8b4';x.beginPath();x.moveTo(-42,-11);x.quadraticCurveTo(-6,-30,29,-72);x.quadraticCurveTo(14,-34,4,-6);x.closePath();x.fill();x.strokeStyle='rgba(120,90,50,.5)';x.lineWidth=1;x.stroke()}
 else{[[-18,48],[12,58],[36,40]].forEach(([mx,h],i)=>{x.lineWidth=2;x.strokeStyle='#3a2616';x.beginPath();x.moveTo(mx,-2);x.lineTo(mx,-h-6);x.stroke();
   if(i<2){x.fillStyle='#ece2c8';x.beginPath();x.moveTo(mx-14,-h);x.quadraticCurveTo(mx+4,-h*.6,mx-14,-10);x.lineTo(mx+14,-10);x.quadraticCurveTo(mx+20,-h*.6,mx+14,-h);x.closePath();x.fill();
    if(type==='croix'){x.fillStyle='#a8201c';x.fillRect(mx-3,-h+8,6,h-24);x.fillRect(mx-10,-h*.62,20,6)}else if(type==='roi'){x.fillStyle='#c8a030';x.font='14px serif';x.textAlign='center';x.fillText('⚜',mx+2,-h*.5)}}
   else{x.fillStyle='#ece2c8';x.beginPath();x.moveTo(mx,-h);x.lineTo(mx+18,-8);x.lineTo(mx-4,-8);x.closePath();x.fill()}});
  x.beginPath();x.moveTo(56,-6);x.lineTo(78,-22);x.stroke()}
 x.restore()}
function prl306Ile(x,cx,cy,R,col,seed){prl306Mont(x,cx-R*1.3,cx+R*1.3,cy+R*.25,R*.95,seed||3,'#4e6a3a','#2c4426',true)}
// une montagne peinte : crête irrégulière, dégradé, forêts en touches, ravines, brume au pied
function prl306Mont(x,x0,x1,by,hh,seed,cTop,cBot,foret){const N=90,r=i=>{const v=Math.sin((i+seed*17)*12.9898)*43758.5453;return v-Math.floor(v)};const P=[];
 for(let i=0;i<=N;i++){const u=i/N,env=Math.pow(Math.sin(Math.PI*u),.8),n=.55*Math.sin(u*7+seed)+.3*Math.sin(u*17+seed*2)+.15*Math.sin(u*41+seed*3);P.push([x0+(x1-x0)*u,by-hh*env*(.78+.22*n)])}
 const g=x.createLinearGradient(0,by-hh,0,by);g.addColorStop(0,cTop);g.addColorStop(1,cBot);x.fillStyle=g;x.beginPath();x.moveTo(x0,by);P.forEach(p=>x.lineTo(p[0],p[1]));x.lineTo(x1,by);x.closePath();x.fill();
 x.save();x.clip();
 // les ravines : traits sombres qui descendent de la crête
 for(let i=0;i<14;i++){const u=.08+r(i)*.84,p=P[Math.round(u*N)];x.strokeStyle='rgba(15,25,12,.35)';x.lineWidth=1+r(i+40)*2.5;x.beginPath();x.moveTo(p[0],p[1]+4);let X=p[0],Y=p[1]+4;for(let j=0;j<8;j++){X+=(r(i*9+j)-.5)*10;Y+=(by-p[1])/8;x.lineTo(X,Y)}x.stroke()}
 // la lumière sur le flanc gauche, l'ombre à droite
 const lg=x.createLinearGradient(x0,0,x1,0);lg.addColorStop(0,'rgba(255,240,200,.16)');lg.addColorStop(.5,'rgba(0,0,0,0)');lg.addColorStop(1,'rgba(0,0,0,.25)');x.fillStyle=lg;x.fillRect(x0,by-hh,x1-x0,hh);
 if(foret)for(let i=0;i<900;i++){const u=r(i*3.1),p=P[Math.round(u*N)],y=p[1]+8+r(i*5.3)*(by-p[1]-8),X=x0+(x1-x0)*u+(r(i*7.7)-.5)*8,s=1+r(i*2.9)*2;x.fillStyle='rgba('+(25+r(i)*30|0)+','+(48+r(i+1)*36|0)+','+(20+r(i+2)*18|0)+',.45)';x.beginPath();x.ellipse(X,y,s*1.4,s,0,0,7);x.fill();x.fillStyle='rgba(170,200,120,.14)';x.beginPath();x.arc(X-s*.3,y-s*.3,s*.45,0,7);x.fill()}
 x.restore();const hz=x.createLinearGradient(0,by-hh*.25,0,by);hz.addColorStop(0,'rgba(220,230,230,0)');hz.addColorStop(1,'rgba(220,230,230,.35)');x.fillStyle=hz;x.fillRect(x0,by-hh*.25,x1-x0,hh*.25)}
function prl306Mer(x,W,H,t,y0){const g=x.createLinearGradient(0,y0,0,H);g.addColorStop(0,'#3d7d92');g.addColorStop(1,'#163a4e');x.fillStyle=g;x.fillRect(0,y0,W,H-y0);x.strokeStyle='rgba(220,240,240,.25)';for(let i=0;i<9;i++){const y=y0+10+i*(H-y0)/9;x.beginPath();for(let X=0;X<=W;X+=12)x.lineTo(X,y+Math.sin(X*.05+t*1.5+i)*2);x.stroke()}}
